# C Program for Processing Votes

Here's a complete C program that reads candidate names and votes from a file, processes them, and writes results to an output file:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_CANDIDATES 50
#define MAX_NAME_LENGTH 50
#define MAX_VOTES 1000

typedef struct {
    char name[MAX_NAME_LENGTH];
    int score;
} Candidate;

int main() {
    FILE *inputFile, *outputFile;
    char candidates[MAX_CANDIDATES][MAX_NAME_LENGTH];
    char votes[MAX_VOTES][MAX_NAME_LENGTH];
    int candidateCount = 0;
    int voteCount = 0;
    int validVotes = 0;
    int invalidVotes = 0;
    Candidate results[MAX_CANDIDATES];
    int maxScore = 0;
    int winnerCount = 0;

    // Open input file
    inputFile = fopen("votes.txt", "r");
    if (inputFile == NULL) {
        printf("Error opening votes.txt file.\n");
        return 1;
    }

    // Read candidate names first
    char line[MAX_NAME_LENGTH];
    while (fgets(line, sizeof(line), inputFile)) {
        // Remove newline character
        line[strcspn(line, "\n")] = '\0';

        // Empty line marks end of candidates section
        if (strlen(line) == 0) {
            break;
        }

        // Skip comments (lines starting with #)
        if (line[0] == '#') {
            continue;
        }

        // Copy candidate name
        strcpy(candidates[candidateCount], line);
        candidateCount++;

        if (candidateCount >= MAX_CANDIDATES) {
            printf("Too many candidates. Maximum supported is %d.\n", MAX_CANDIDATES);
            break;
        }
    }

    // Read votes
    while (fgets(line, sizeof(line), inputFile)) {
        // Remove newline character
        line[strcspn(line, "\n")] = '\0';

        // Skip empty lines and comments
        if (strlen(line) == 0 || line[0] == '#') {
            continue;
        }

        strcpy(votes[voteCount], line);
        voteCount++;

        if (voteCount >= MAX_VOTES) {
            printf("Too many votes. Maximum supported is %d.\n", MAX_VOTES);
            break;
        }
    }

    fclose(inputFile);

    // Initialize candidate scores
    for (int i = 0; i < candidateCount; i++) {
        strcpy(results[i].name, candidates[i]);
        results[i].score = 0;
    }

    // Process votes
    for (int i = 0; i < voteCount; i++) {
        int found = 0;

        // Check if vote matches any candidate
        for (int j = 0; j < candidateCount; j++) {
            if (strcmp(votes[i], candidates[j]) == 0) {
                results[j].score++;
                validVotes++;
                found = 1;
                break;
            }
        }

        if (!found) {
            invalidVotes++;
        }
    }

    // Find maximum score
    for (int i = 0; i < candidateCount; i++) {
        if (results[i].score > maxScore) {
            maxScore = results[i].score;
        }
    }

    // Count winners (candidates with max score)
    for (int i = 0; i < candidateCount; i++) {
        if (results[i].score == maxScore) {
            winnerCount++;
        }
    }

    // Open output file
    outputFile = fopen("resultats.txt", "w");
    if (outputFile == NULL) {
        printf("Error creating resultats.txt file.\n");
        return 1;
    }

    // Write invalid votes first
    for (int i = 0; i < voteCount; i++) {
        int found = 0;

        for (int j = 0; j < candidateCount; j++) {
            if (strcmp(votes[i], candidates[j]) == 0) {
                found = 1;
                break;
            }
        }

        if (!found) {
            fprintf(outputFile, "Vote invalide : %s\n", votes[i]);
        }
    }

    // Write summary statistics
    fprintf(outputFile, "Total des votes : %d\n", voteCount);
    fprintf(outputFile, "Votes valides : %d\n", validVotes);
    fprintf(outputFile, "Votes invalides : %d\n", invalidVotes);

    // Write candidate results in order
    fprintf(outputFile, "Resultats :\n");
    for (int i = 0; i < candidateCount; i++) {
        fprintf(outputFile, "%s : %d\n", results[i].name, results[i].score);
    }

    // Write winner(s)
    if (winnerCount == 1) {
        fprintf(outputFile, "Gagnant : ");
    } else {
        fprintf(outputFile, "Gagnants : ");
    }

    int firstWinner = 1;
    for (int i = 0; i < candidateCount; i++) {
        if (results[i].score == maxScore) {
            if (!firstWinner) {
                fprintf(outputFile, ", ");
            }
            fprintf(outputFile, "%s", results[i].name);
            firstWinner = 0;
        }
    }
    fprintf(outputFile, "\n");

    fclose(outputFile);

    printf("Results have been written to resultats.txt\n");

    return 0;
}
```

## Program Explanation:

1. **File Reading**:
   - The program reads candidate names from the input file first (until an empty line or comment)
   - Then reads all votes from the remaining lines

2. **Processing**:
   - Counts valid votes (votes that match candidate names)
   - Counts invalid votes (votes that don't match any candidate)
   - Calculates scores for each candidate

3. **Output Generation**:
   - Writes all invalid votes first with the "Vote invalide : " prefix
   - Writes summary statistics (total, valid, invalid votes)
   - Writes each candidate's name and score in the order they appeared in the input
   - Writes the winner(s) with the highest score

4. **Edge Cases Handled**:
   - Empty lines and comments in the input file
   - Multiple winners (in case of a tie)
   - Maximum limits for candidates and votes
   - File opening errors

## Example Input File (votes.txt):
```
Alice
Bob
Charlie

Alice
Bob
Alice
Charlie
David
Alice
Bob
```

## Example Output File (resultats.txt):
```
Vote invalide : David
Total des votes : 6
Votes valides : 5
Votes invalides : 1
Resultats :
Alice : 3
Bob : 2
Charlie : 1
Gagnant : Alice
```

The program adheres to the exact output format specified and handles all the required cases.

